package com.example.customerrouting.agent; import com.example.customerrouting.routing.*; import com.example.customerrouting.skill.*; import com.example.customerrouting.websocket.*; import jakarta.transaction.*; import org.springframework.stereotype.*; import java.util.*;
@Service public class AgentService { private final AgentRepository agents; private final SkillRepository skills; private final PendingEnquiryService pending; private final EventPublisher events; public AgentService(AgentRepository a,SkillRepository s,PendingEnquiryService p,EventPublisher e){agents=a;skills=s;pending=p;events=e;} @Transactional public Agent create(String n,Set<Language>l,Set<String>c,int cap){Set<Skill> ss=new HashSet<>(skills.findByCodeIn(c));if(ss.size()!=c.size())throw new IllegalArgumentException("Unknown skill code");Agent a=agents.save(new Agent(n,l,ss,cap));events.publish(new DomainEvent("AGENT_CREATED",null,a.getId(),Map.of("name",a.getName())));return a;} public List<Agent> all(){return agents.findAllWithDetails();} public Agent one(UUID id){return agents.findByIdWithDetails(id).orElseThrow(()->new NoSuchElementException("Agent not found"));} @Transactional public Agent status(UUID id,AgentStatus s){Agent a=one(id);AgentStatus old=a.getStatus();a.setStatus(s);events.publish(new DomainEvent("AGENT_STATUS_CHANGED",null,id,Map.of("status",s)));if(s==AgentStatus.ONLINE&&old!=AgentStatus.ONLINE) pending.retry();return a;} @Transactional public Agent capacity(UUID id,int cap){Agent a=one(id);if(cap<a.getActiveEnquiryCount())throw new IllegalArgumentException("Capacity cannot be lower than active count");a.setMaxCapacity(cap);events.publish(new DomainEvent("AGENT_CAPACITY_CHANGED",null,id,Map.of("maxCapacity",cap)));pending.retry();return a;} @Transactional public Agent heartbeat(UUID id){Agent a=one(id);a.heartbeat();return a;} }
